    with open(path) as f:
        tokens = f.read().split()
    w, h, steps = int(tokens[0]), int(tokens[1]), int(tokens[2])
    grid = np.array(tokens[3:3 + w * h], dtype=np.uint32)
    if grid.size != w * h:
        raise ValueError("not enough cells")
    return w, h, steps, grid


