import subprocess, sys, random, os
import pytest

HERE = os.path.dirname(os.path.abspath(__file__))


def ref(w, h, steps, g):
    for _ in range(steps):
        n = [[0] * w for _ in range(h)]
        for y in range(h):
            for x in range(w):
                c = g[y][x]
                l = g[y][max(x - 1, 0)]; r = g[y][min(x + 1, w - 1)]
                u = g[max(y - 1, 0)][x]; d = g[min(y + 1, h - 1)][x]
                n[y][x] = (4 * c + l + r + u + d) // 8
        g = n
    return g


@pytest.mark.parametrize("w,h,steps", [(1, 1, 5), (3, 2, 0), (7, 5, 10), (17, 9, 50), (1, 8, 3), (9, 1, 3)])
def test_matches_reference(tmp_path, w, h, steps):
    rnd = random.Random(w * 100 + h)
    g = [[rnd.choice([0, 1000000, rnd.randint(0, 1000000)]) for _ in range(w)] for _ in range(h)]
    p = tmp_path / "in.txt"
    p.write_text(f"{w} {h} {steps}\n" + "\n".join(" ".join(map(str, r)) for r in g) + "\n")
    out = subprocess.run([sys.executable, os.path.join(HERE, "main.py"), str(p)],
                         capture_output=True, text=True, check=True).stdout
    e = ref(w, h, steps, g)
    exp = "\n".join(" ".join(map(str, r)) for r in e) + f"\nSUM {sum(map(sum, e))}\n"
    assert out == exp
